import { expect, test } from '@playwright/test';

/**
 * A HELP topic (the HELP handoff, board 1A; card c208), in a real browser, at
 * tablet-portrait: the article's parts and STILL STUCK (the topics' index
 * beside it shows from 1024 px, which no frame project is).
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/design/handoff/Help.dc.html, its `topic` state
 * Extracted at 2026-10-31T03:05:38.228Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region10: '#extensions',
	region11: '#online',
	region12: '#download',
	region13: '#queue',
	region14: '.stuck .st'
};

test('a HELP topic (Help 1A): frame matches the handoff', async ({ page }) => {
	await page.goto(`${base}/help/downloading`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('a HELP topic (Help 1A): region10 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/help/downloading`);
	await expect(page.locator(SEL.region10)).toBeVisible();

	const region10Style = await page.locator(SEL.region10).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			justifyContent: cs.justifyContent,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom,
			paddingLeft: cs.paddingLeft,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing,
			lineHeight: cs.lineHeight
		};
	});
	expect(region10Style.display).toBe('flex');
	expect(region10Style.alignItems).toBe('baseline');
	expect(region10Style.justifyContent).toBe('space-between');
	expect(region10Style.rowGap).toBe('12px');
	expect(region10Style.columnGap).toBe('12px');
	expect(region10Style.paddingTop).toBe('32px');
	expect(region10Style.paddingRight).toBe('24px');
	expect(region10Style.paddingBottom).toBe('12px');
	expect(region10Style.paddingLeft).toBe('24px');
	expect(region10Style.fontSize).toBe('13px');
	expect(region10Style.fontWeight).toBe('500');
	expect(region10Style.letterSpacing).toBe('0.78px'); // authored 0.06em
	expect(region10Style.lineHeight).toBe('15.6px');
});

